const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 1.4 1.4m10 10 1.4 1.4M5.6 18.4 1.4-1.4m10-10 1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8c-8 0-7-7-3-5 2 1 3 5 3 5Zm0 0c8 0 7-7 3-5-2 1-3 5-3 5Z',spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z',card:'M5 7V4h15v13h-3M3 8h14v13H3zM6 12h8M6 16h4',chart:'M4 3v17h17M7 14l4-5 4 3 5-7',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',upload:'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',download:'M12 3v14m-5-5 5 5 5-5M4 17v4h16v-4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 3h4l1 3 3 1 3 2v5l-3 1-1 3-3 3h-4l-1-3-3-1-3-2v-5l3-1 1-3 3-3Z',history:'M3 10a9 9 0 1 1 1 7M3 4v6h6m3-3v6l4 2',leaf:'M19 3C7 2 2 8 5 16c8 4 15-2 14-13ZM3 21 14 10',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4M12 15v2',note:'m16 3 5 5-12 12-6 1 1-6L16 3ZM13 6l5 5',archive:'M3 3h18v5H3zM5 8v13h14V8M9 12h6',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',logout:'M9 3H4v18h5M9 12h12m-4-4 4 4-4 4'};
