function art(){return `<svg class="hero-art" viewBox="0 0 290 230" aria-hidden="true"><ellipse class="orbit" cx="149" cy="122" rx="121" ry="61" transform="rotate(-26 149 122)"/><ellipse class="orbit" cx="149" cy="122" rx="109" ry="85" transform="rotate(35 149 122)"/><path class="star" d="m243 39 4 13 14 4-14 4-4 13-4-13-14-4 14-4zM46 136l3 9 10 3-10 3-3 10-3-10-10-3 10-3z"/><g transform="rotate(-13 150 110)"><rect x="85" y="55" width="132" height="129" rx="18" fill="#172f2370"/><rect x="78" y="46" width="132" height="129" rx="18" fill="#f0f3d9"/><rect x="78" y="46" width="132" height="33" rx="18" fill="#dce7b6"/><path d="M78 65h132v14H78z" fill="#dce7b6"/><path d="M109 37v20m70-20v20" stroke="#8ea179" stroke-width="7" stroke-linecap="round"/><circle cx="143" cy="122" r="30" fill="#dfe9bf"/><path d="m127 123 11 10 22-23" stroke="#496d41" stroke-width="7" fill="none" stroke-linecap="round" stroke-linejoin="round"/></g><g transform="rotate(18 225 162)"><ellipse cx="225" cy="169" rx="30" ry="31" fill="#b69d50"/><circle cx="225" cy="163" r="30" fill="#e7d38d"/><circle cx="225" cy="163" r="23" fill="none" stroke="#b7a25e" stroke-width="1.5"/><text x="225" y="174" text-anchor="middle" font-size="32" fill="#9c8545">✳</text></g><circle cx="63" cy="66" r="6" fill="#c9d9a1"/><path d="m114 202 4 10 10 4-10 4-4 10-4-10-10-4 10-4z" fill="#9db987"/></svg>`;}

const category=id=>state.categories.find(c=>c.id===id)||{name:'特别约定',emoji:'🎁'},qname=id=>QUADRANTS.find(q=>q[0]===id)?.[1]||'普通计划';
const errorSlot='<div class="error-text" role="alert"></div>';
function field(label,name,type='text',value='',extra='',hint=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}${hint?' aria-describedby="f-'+name+'-hint"':''}>${hint?'<p id="f-'+name+'-hint" class="field-help">'+esc(hint)+'</p>':''}</div>`;}
function select(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`;}
function textarea(label,name,value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;}
function actions(label='保存'){return `${errorSlot}<div class="form-actions"><button type="button" class="btn secondary" data-action="close">取消</button><button class="btn" type="submit">${label}</button></div>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function openDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-action="close" aria-label="关闭">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function heading(eyebrow,title,subtitle,button=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
function empty(emoji,title,text,button='',full=false){return `<div class="empty ${full?'full':''}"><div class="empty-icon">${emoji}</div><h3>${title}</h3><p>${text}</p>${button}</div>`;}
async function api(route,body,options={}){const headers={};if(body!==undefined){if(state)body={space_id:state.space.id,...body};headers['Content-Type']='application/json';if(state?.csrf)headers['X-CSRF-Token']=state.csrf;headers['Idempotency-Key']=options.key||crypto.randomUUID();}const r=await fetch(new URL(`api/${route}`,location.href.split(/[?#]/)[0]),{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',signal:AbortSignal.timeout(25000)});const data=await r.json();if(!r.ok){if(r.status===401&&state){state=null;renderAuth();}throw new Error(data.error||'请求未能完成');}return data;}
async function refresh(){
  let next=await api('state'+(space?'?space='+encodeURIComponent(space):''));
  if(!space){let remembered='';try{remembered=localStorage.getItem(roomMemoryKey(next.user.id))||'';}catch{}
    const selected=initialRoom(next,remembered);if(selected!==next.space.id)next=await api('state?space='+encodeURIComponent(selected));}
  state=next;space=state.space.id;try{localStorage.setItem(roomMemoryKey(state.user.id),space);}catch{}
  await community.load(page);render();if(!location.hash)community.notify();
}
async function boot(){try{status=await api('status');if(status.loggedIn){await refresh();await incoming();}else{authMode='welcome';renderAuth();const h=new URLSearchParams(location.hash.slice(1));if(h.has('auth-error'))toast(h.get('auth-error'));if(h.has('join'))joinDialog(h.get('join'));}}catch(e){app.innerHTML=`<div class="loading"><span class="brand-symbol">✳</span><p>${esc(e.message)}</p><button class="btn" data-action="reload">重新连接</button></div>`;}}
async function incoming(){const h=new URLSearchParams(location.hash.slice(1));if(h.has('join')||pendingInvite){joinDialog(pendingInvite?.code||h.get('join'));return;}if(h.has('auth-error')){toast(h.get('auth-error'));history.replaceState(null,'',location.pathname);}if(h.has('github-bind')){bindPending=h.get('github-bind');openDialog('确认绑定 GitHub',`<p>将刚刚授权的 GitHub 绑定到当前账号「${esc(state.user.name)}」。</p><form id="github-confirm-form">${actions('确认绑定到这个账号')}</form>`);}if(h.has('redeem')){shareToken=h.get('redeem');try{const r=await api('share/inspect',{token:shareToken});fulfillDialog(r.card,shareToken);}catch(e){openDialog('这份心愿暂时打不开',`<p>${esc(e.message)}</p><button class="btn full-width" data-action="close">知道了</button>`);}}}
const roomLabel=r=>r.family_id?'🏡 '+r.family_name:!r.giver_id?'🌱 我的个人计划':r.learner_id===state.user.id?'🎁 我向 '+r.giver_name+' 领奖':'💌 我给 '+r.learner_name+' 发奖';
function isPersonalRewardView(){return state.space.personal&&!state.admin&&!state.prizes.length;}
function rewardRoomLinks(){return (state.rewardRooms||[]).map(r=>`<button class="room-link" data-action="reward-room" data-id="${r.id}"><span>${esc(roomLabel(r))}</span><small>${r.prizeCount?`${r.prizeCount} 款已上架心愿卡`:'心愿正在准备中'} · 点这里进入</small></button>`).join('');}
function rewardRoomPicker(){const hasRooms=state.rewardRooms?.length;return `<section class="panel reward-room-picker"><h1>${hasRooms?'🎁 奖励在朋友的小窝里':'🌱 先和伙伴建一间奖励小窝'}</h1><p>${hasRooms?'你现在在“个人计划”。去下面的小窝，就能看见朋友准备的奖品啦。':'个人计划只给自己看。邀请一位发奖人，或加入家庭，就能一起做计划、攒币领奖。'}</p>${hasRooms?`<div class="room-list">${rewardRoomLinks()}</div>`:'<button class="btn" data-action="profile">邀请伙伴 / 输入邀请码</button>'}<p class="subtext">每间小窝各自记计划、学习币和卡片。想在哪里领奖，就在那里打卡哦。</p></section>`;}
function personalPlanHint(){if(page!=='today'||!isPersonalRewardView()||!state.rewardRooms?.length)return '';return `<details class="personal-room-hint"><summary>🎁 想攒币领奖？进入朋友的奖励小窝</summary><p class="subtext">这里是仅自己可见的个人计划。奖励小窝的计划和学习币单独计算。</p><div class="room-list">${rewardRoomLinks()}</div></details>`;}
function howTo(){openDialog('小小成就，怎么玩？',`<div class="help-steps"><section><h3>🌱 先种下一个小计划</h3><p>注册只需要昵称、账号和密码。手动添加计划，或粘贴 Markdown 清单；勾选完成就获得学习币，点错了也能撤销。</p></section><section><h3>🏡 和不同朋友，建不同小屋</h3><p>领奖人完成计划、攒币换卡；发奖人准备奖品、兑现奖励。你可以向小明领奖，也给小红发奖，随时继续邀请更多伙伴。</p><p>双人小屋只向两个人开放。家庭最多六人，互相看计划，各自攒币、共用奖池；1–2 位奖品管家负责奖品和核销。不同小屋的计划、学习币和卡片单独计算。个人计划只给自己看，不能把里面的币转进奖励小屋。</p></section><section><h3>💌 邀请码，是一张入屋请柬</h3><p>在“我的小屋与伙伴”里选择邀请方向，系统会生成一次性邀请码，7 天有效。朋友输入后先看清双方身份，再确认建屋；不需要自己编口令。</p></section><section><h3>🎁 把努力换成小心愿</h3><p>学习币可在商城换卡，也可用于抽奖；抽到“下次好运”同样会扣币。小屋里的同品类卡可以合成，万能卡能按等额换品类。</p><p>想兑现时，附购买或充值记录申请报销，把链接交给发奖人。对方实际报销后再确认核销；一张卡只核销一次，剩余额度不返还。</p></section><section><h3>📮 信箱、日记与小屋日志</h3><p>信箱可以加好友、申请查看某一天的动态或日记，不提供聊天。只有本人同意才分享，之后也可撤回。家庭不会自动看到你的私密日记。</p><p>每间小屋都记录打卡、撤销、兑换和奖品设置。关闭小窝由创建人发起，所有伙伴同意才生效；停止新的打卡与兑换，历史和旧卡报销仍保留。</p></section></div><p class="subtext">学习币只在这里记奖励，不是真实货币。模拟投资之后再开放。</p><button class="btn full-width mt" data-action="close">明白啦，开始种心愿</button>`);}
let invitePreviewSequence=0,invitePreviewTimer;
function joinDialog(code=''){
  clearTimeout(invitePreviewTimer);invitePreviewSequence++;
  openDialog('收下朋友的小屋邀请',`<form id="accept-form">${field('邀请码或邀请链接','code','text',code,'required autocomplete="off" maxlength="500" placeholder="把朋友发来的码或链接粘贴到这里"','粘贴后自动核对。看清邀请人和小屋类型，再确认就好。')}<div id="pair-preview" class="pair-preview" aria-live="polite"><p class="subtext">等你粘贴朋友的小请柬。</p></div>${errorSlot}<button id="join-confirm" class="btn full-width mt" type="submit" disabled>先粘贴邀请码</button><button type="button" class="text-btn full-width mt" data-action="preview-pair">重新核对邀请</button></form>`);
  if(code)previewInvite();
}
async function previewInvite(){
  const form=$('#accept-form');if(!form)return;const sequence=++invitePreviewSequence,button=$('#join-confirm'),preview=$('#pair-preview'),error=form.querySelector('.error-text');
  button.disabled=true;delete form.dataset.invitePreview;error.textContent='';let code;
  try{code=readInviteCode($('#f-code').value);}catch(e){preview.textContent='';error.textContent=e.message;button.textContent='请补全邀请码';return;}
  preview.innerHTML='<p class="subtext">正在核对这张小请柬…</p>';button.textContent='正在核对…';
  try{
    const r=await api('invite/preview',{code});if(sequence!==invitePreviewSequence||!document.contains(form))return;
    form.dataset.invitePreview=code;form._preview=r;
    preview.innerHTML=`<div class="pair-box"><strong>${esc(r.name)} <small>@${esc(r.username)}</small></strong><p>${r.direction==='family'?'邀请你加入「'+esc(r.family_name)+'」，一起做计划、攒币领奖。':r.direction==='manager'?'你给 '+esc(r.name)+' 发奖；TA 做计划、收奖励。':esc(r.name)+' 给你发奖；你做计划、收奖励。'}</p><small>${r.existingSpace?'你已经在这间小屋啦，直接进去就好。':r.direction==='family'?r.count+'/6 位成员 · 加入后互相看见计划，日记仍然私密。':'新小屋只向你们两个人开放。'}</small></div>`;
    button.disabled=false;button.textContent=r.existingSpace?'进入已有小屋':state?r.direction==='family'?'确认加入这个家庭':'确认，和 TA 建立小屋':'登录 / 注册后加入';
  }catch(e){if(sequence!==invitePreviewSequence||!document.contains(form))return;preview.textContent='';error.textContent=e.message;button.textContent='暂时无法加入';}
}

function renderAuth(){
  const register=authMode==='register',welcome=authMode==='welcome';
  document.title='小小成就 · 把努力变成小奖励';
  app.innerHTML=`<main class="auth-layout"><section class="auth-story"><div class="brand">${brand()}</div><div><h1>小小努力，<br>换来<em>心愿开花。</em></h1><p>给计划打个勾，把小奖励装进口袋。<br>和愿意互相鼓励的朋友，一起慢慢长大。</p>${art()}</div><div class="auth-bottom">LITTLE EFFORTS. LOVELY REWARDS.</div></section><section class="auth-form-wrap"><div class="auth-form"><div class="eyebrow">YOUR LITTLE WISH GARDEN</div><h2>${welcome?'欢迎来种下小心愿':register?'给自己留一个小角落':'欢迎回来，继续长大'}</h2><p>${welcome?'记计划、攒学习币，让每一点坚持都有回响。':register?'人人都可以注册，不需要邀请码。':'用自己的账号和密码，回到你的小屋。'}</p>
  ${welcome?`<ol class="welcome-steps"><li><span>01</span><div><strong>种下计划</strong><small>手动添加或导入 Markdown，完成就打勾。</small></div></li><li><span>02</span><div><strong>和朋友建小屋</strong><small>可以领奖，也可以发奖；双人小屋或六人家庭，各自攒币。</small></div></li><li><span>03</span><div><strong>攒出小奖励</strong><small>学习币换可爱卡片，拿购买记录兑现心愿。</small></div></li></ol><button class="btn full-width" data-action="auth-mode" data-mode="register">注册我的账号 ${icon('arrow')}</button><button class="btn secondary full-width mt" data-action="auth-mode" data-mode="login">已有账号，登录</button>`:`${pendingInvite?`<div class="notice soft">登录或注册后，会再请你确认与 ${esc(pendingInvite.preview.name)} 的小屋邀请。</div>`:''}<form id="auth-form" data-mode="${authMode}">${register?field('怎么称呼你','name','text','','required maxlength="24" autocomplete="nickname" placeholder="例如：小芽"','给伙伴看的昵称，1–24 个字，中文也可以。'):''}${field(register?'登录账号':status.emailEnabled?'账号或已验证邮箱':'登录账号','username','text','',`required autocomplete="username" ${register?'pattern="[a-zA-Z0-9_]{3,32}" maxlength="32" title="3–32 位英文字母、数字或下划线" placeholder="例如：xiaoya_01"':'placeholder="输入注册时的账号"'}`,register?'自己起一个：3–32 位英文字母、数字或下划线，不含空格。重名时会提醒你换一个。':'')}${field('登录密码','password','password','',`required minlength="10" maxlength="128" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'设置至少 10 个字符的密码':'输入你的登录密码'}"`,register?'10–128 个字符，建议组合字母和数字；以后登录就用它。':'')}${errorSlot}<button class="btn full-width" type="submit">${register?'注册，开始我的计划':'登录我的小屋'} ${icon('arrow')}</button></form>${status.githubEnabled?'<button class="btn secondary full-width mt" data-action="github">使用 GitHub 登录</button>':''}<div class="auth-switch">${register?'已经有账号？':'还没有账号？'} <button data-action="auth-mode" data-mode="${register?'login':'register'}">${register?'去登录':'免费注册'}</button></div>`}
  <div class="welcome-links"><button class="text-btn" data-action="accept-invite">💌 我有邀请码</button><button class="text-btn" data-action="help">🌱 第一次来？看看怎么玩</button></div>${status.demo?'<button class="btn secondary full-width mt" data-action="demo">逛逛示例小屋</button>':''}<p class="auth-footnote">${status.apkAvailable?'<a href="./downloads/starlight.apk" download>下载安卓 App</a> · ':''}<button data-action="install">添加到手机主屏幕</button><br>心愿由这间小屋的发奖人，在现实中为你兑现。</p></div></section></main>`;
}

const community=communityUI({getState:()=>state,api,refresh,render,navigate:async(next,room)=>{page=next;if(room)space=room;await refresh();},openDialog,dialog,esc,time,field,textarea,actions,toast,roomLabel});
const navs=[['today','sun','今日计划'],['shop','gift','心愿商城'],['cards','card','我的卡包'],['lucky','spark','幸运时刻'],['growth','leaf','成长空间']];
function render(){if(!state)return;dirty=false;if(state.space.status!=='active'&&page==='admin')adminTab='redemptions';const title=navs.find(n=>n[0]===page)?.[2]||({admin:'发奖小桌',ledger:'学习币账本',inbox:'我的信箱',logs:'小屋日志'}[page]);document.title=`${title} · 小小成就`;app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-page="today">${brand()}</a><div class="nav-label">MY LITTLE WISH GARDEN</div><nav class="nav" aria-label="主要导航">${navs.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="profile" data-action="profile"><span class="avatar">${esc(state.user.name.slice(0,1))}</span><span><strong>${esc(state.user.name)}</strong><small>我的小屋与伙伴</small></span>${icon('settings')}</button></div></aside><div class="layout"><header class="topbar"><div class="breadcrumb">心愿花园 ${icon('chevron')} <strong>${title}</strong></div><a class="brand mobile-brand" href="#" data-page="today">${brand()}</a><div class="top-actions">${community.badge()}<button class="coin-pill" data-page="ledger">${coinIcon}<strong>${coins(state.balance)}</strong><span>${cn()}</span></button><button class="avatar" data-action="profile" aria-label="我的小屋与伙伴">${esc(state.user.name.slice(0,1))}</button></div></header><main class="main">${state.demo?'<div class="demo-banner">示例空间 · 小凡由晴天支持，也在支持小芽。这里的余额和卡片仅供体验。</div>':''}<div class="space-bar"><label for="space-select">🏡 当前小屋</label><select id="space-select">${[...state.rooms,...state.archivedRooms.filter(r=>r.id===state.space.id||r.family_id&&r.family_id===state.family?.id)].map(r=>`<option value="${r.id}" ${state.space.id===r.id||r.family_id&&r.family_id===state.family?.id?'selected':''}>${esc(roomLabel(r))}</option>`).join('')}
</select><button class="text-btn room-settings-btn" data-action="room-settings" aria-label="小屋设置与成员">${icon('settings')}</button>${state.admin?'<button class="text-btn" data-page="admin">准备奖励 '+icon('settings')+'</button>':'<button class="text-btn" data-action="profile">我的伙伴 '+icon('chevron')+'</button>'}</div>${community.familyStrip()}${personalPlanHint()}${state.space.status!=='active'?'<div class="notice soft">这间小屋已收进历史。可以查看记录，或继续兑现旧卡。<button class="text-btn" data-action="profile">切换小屋</button></div>':''}${state.balance<0?`<div class="notice error">撤销任务后还有 ${coins(-state.balance)} ${cn()}待补足。补足后即可继续兑换、合成和兑奖。</div>`:''}${({today:todayPage,shop:shopPage,cards:cardsPage,lucky:luckyPage,growth:growthPage,admin:adminPage,ledger:ledgerPage,inbox:community.inboxPage,logs:community.logsPage}[page]||todayPage)()}</main></div>`;if(page==='admin'&&adminTab==='odds')updateOddsForm();if(state.space.status!=='active'){for(const b of app.querySelectorAll('[data-action="complete"],[data-action="task"],[data-action="import"],[data-action="note"],[data-action="archive"],[data-action="buy"],[data-action="draw"],[data-action="merge"],[data-action="convert"],[data-action="claim-bonus"]'))b.disabled=true;}}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><button class="check ${t.done?'checked':''}" data-action="complete" data-id="${t.id}" aria-label="${t.done?'取消完成':'完成任务'}：${esc(t.title)}" aria-pressed="${!!t.done}" ${!state.space.isSelf?'disabled':''}>${icon('check')}</button><div class="task-body"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span class="category">${esc(t.category)}</span><span>${t.recurrence==='daily'?'每天重复':t.start_date<state.day?'待完成':'单次计划'}</span>${t.note?'<span title="'+esc(t.note)+'">有完成记录</span>':''}</div></div><span class="task-reward">${t.done?'已得':'+'}${coins(t.awarded||t.points)}</span>${state.space.isSelf?`<div class="task-actions"><button class="icon-button" data-action="note" data-id="${t.id}" aria-label="记录心得：${esc(t.title)}">${icon('note')}</button><button class="icon-button" data-action="archive" data-id="${t.id}" aria-label="归档：${esc(t.title)}">${icon('archive')}</button></div>`:''}</div>`;}
function todayPage(){
  const done=state.tasks.filter(t=>t.done).length,filtered=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));
  return `<section class="panel plans-panel"><div class="plan-heading"><div><h1>${state.space.isSelf?'今日计划':esc(state.space.name)+'的今日计划'}</h1><p>${done} / ${state.tasks.length} 已完成 · 今日 +${coins(state.earnedToday)} ${cn()}${state.space.isSelf?'':' · 由本人打卡'}</p></div>${state.space.isSelf?'<div class="plan-buttons"><button class="btn secondary sm" data-action="import">'+icon('upload')+' 导入</button><button class="btn sm" data-action="task">'+icon('plus')+' 添加</button></div>':''}</div>${dailyBonusPanel()}<div class="plan-toolbar"><div class="task-tabs">${[['all','全部'],['todo','待完成'],['done','已完成']].map(([f,l])=>`<button data-action="task-filter" data-value="${f}" class="${taskFilter===f?'active':''}">${l}</button>`).join('')}</div><div class="segmented">${[['list','清单'],['quadrants','四象限']].map(([v,n])=>`<button data-action="task-view" data-value="${v}" class="${taskView===v?'active':''}">${n}</button>`).join('')}</div></div>${taskView==='list'?filtered.map(taskRow).join('')||empty('🌱',state.tasks.length?'这一栏已经清空啦':'今天想完成什么？',state.space.isSelf?'添加一个小计划，或粘贴你写好的 Markdown。':'等伙伴种下计划，就能在这里看到进展。'):`<div class="quadrant-grid">${QUADRANTS.slice(1).map(([q,n],i)=>`<section class="quadrant q${i+1}"><div class="quadrant-head"><h3>${['🔥','⏳','🌱','☁️'][i]} ${n}</h3><small>${filtered.filter(t=>t.quadrant===q).length}</small></div>${filtered.filter(t=>t.quadrant===q).map(taskRow).join('')||'<p class="quadrant-empty">暂时没有计划</p>'}</section>`).join('')}</div>${filtered.some(t=>t.quadrant==='none')?'<div class="normal-plans"><h3>🌼 普通计划</h3>'+filtered.filter(t=>t.quadrant==='none').map(taskRow).join('')+'</div>':''}`}${state.space.isSelf?'<button class="add-task-line" data-action="task">'+icon('plus')+' 添加一个小计划</button>':''}${state.futureTasks.length?'<details class="future-plans"><summary>即将开始 · '+state.futureTasks.length+' 个</summary>'+state.futureTasks.map(t=>`<div class="record-row"><div class="record-main"><strong>${esc(t.title)}</strong><small>${t.start_date} · ${qname(t.quadrant)}</small></div></div>`).join('')+'</details>':''}</section>${state.space.personal&&!state.rewardRooms?.length?'<p class="personal-invite">这里的计划只给自己看。<button class="text-btn" data-action="profile">邀请朋友，建一间奖励小屋 →</button></p>':''}`;
}

function rewardArt(p){return `<div class="wish-art ${esc(p.tone)}"><span class="wish-tier">${esc(p.tier)} ✧</span><span class="wish-sticker">${esc(p.emoji)}</span><span class="wish-spark s1">✦</span><span class="wish-spark s2">✧</span><span class="wish-spark s3">♡</span><div class="wish-value">${p.face_cents?'<small>¥</small>'+yuan(p.face_cents):'小心愿'}<span>${p.face_cents?'报销额度':'专属奖励'}</span></div></div>`;}
function filterChips(active,action,values){return `<div class="chips scroll-chips">${values.map(([v,l])=>`<button class="chip ${active===v?'active':''}" data-action="${action}" data-value="${v}">${l}</button>`).join('')}</div>`;}
function shopPage(){if(isPersonalRewardView())return rewardRoomPicker();const prizes=state.prizes.filter(p=>shopFilter==='all'||p.category===shopFilter);return `${heading('LITTLE WISHES, LOVELY REWARDS','努力攒一攒，心愿就开花。','同样的人民币额度，学习最划算；然后是运动、衣鞋包、首饰香水、吃喝。')}<div class="notice soft">卡片额度用于凭购买或充值记录向发奖人报销。兑换后进入卡包，可合成、转换或申请报销。</div>${filterChips(shopFilter,'shop-filter',[['all','全部心愿'],...state.categories.map(c=>[c.id,c.emoji+' '+c.name])])}<div class="reward-grid wish-grid">${prizes.map(p=>`<article class="reward-card wish-card">${rewardArt(p)}<div class="reward-content"><span class="category">${category(p.category).name}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="reward-bottom"><span class="price">${coinIcon}${coins(p.cost)}<small>学习币</small></span>${state.space.isSelf?`<button class="btn sm" data-action="buy" data-id="${p.id}" ${p.stock<=0||state.balance<p.cost?'disabled':''}>${p.stock<=0?'暂时兑完了':state.balance<p.cost?'还差 '+coins(p.cost-state.balance):'抱走这张卡'}</button>`:''}</div><div class="reward-stock"><span>剩余 ${p.stock} 张</span><span>${p.wait_days?'等待 '+p.wait_days+' 天':'随时申请'}</span></div></div></article>`).join('')||empty('🌷','心愿还在准备中',state.admin?'挑选模板或添加自定义奖励，就可以开张啦。':'邀请你的发奖人，为你准备第一份心愿。',state.admin?'<button class="btn" data-page="admin">布置心愿商城</button>':'',true)}</div>`;}
function cardsPage(){if(isPersonalRewardView()&&!state.cards.length)return rewardRoomPicker();const cards=state.cards.filter(c=>cardFilter==='all'||c.status===cardFilter),value=state.cards.filter(c=>['ready','requested'].includes(c.status)).reduce((s,c)=>s+c.face_cents,0);return `${heading('YOUR POCKET OF LITTLE JOYS','口袋里，装着小小的快乐。',`可用与待核销额度 ¥${yuan(value)}。每张卡都是努力留下的礼物。`,state.space.isSelf?'<button class="btn secondary" data-action="merge">✨ 合成大心愿</button>':'')}${filterChips(cardFilter,'card-filter',[['ready','待使用'],['requested','待报销'],['fulfilled','已核销'],['all','全部记录']])}<div class="card-grid wish-grid">${cards.map(c=>`<article class="ticket wish-ticket ${['merged','converted','fulfilled'].includes(c.status)?'used-ticket':''}">${rewardArt(c)}<div class="ticket-bottom"><h3>${esc(c.title)}</h3><div class="ticket-status">${{ready:Date.parse(c.available)>Date.now()?date(c.available)+' 起可申请':'等待心愿兑现',requested:'已申请 · 等发奖人核销',fulfilled:'已核销',merged:'已合成到新卡',converted:'已转换到新卡'}[c.status]}</div><p>${esc(c.description)}</p>${c.status==='fulfilled'?`<p>实际报销 ¥${yuan(c.paid_cents)} · ${esc(c.delivery_note)}</p>`:''}${state.space.isSelf&&c.status==='ready'?`<button class="btn full-width" data-action="redeem" data-id="${c.id}" ${Date.parse(c.available)>Date.now()||state.balance<0?'disabled':''}>${c.face_cents?'拿记录来报销':'申请兑现'}</button>${c.category==='universal'?`<button class="text-btn full-width mt" data-action="convert" data-id="${c.id}">🌈 换成另一种心愿</button>`:''}`:''}${state.space.isSelf&&c.status==='requested'?`<button class="btn full-width" data-action="share" data-id="${c.id}">生成核销分享链接</button><button class="text-btn mt" data-action="cancel-redeem" data-id="${c.id}">撤回申请</button>`:''}<small class="ticket-code">${esc(c.id.slice(0,8))} · ${date(c.created)} 收入卡包</small></div></article>`).join('')||empty('💌','这一格，还等着新的快乐','去完成小计划，再来挑选心愿。','',true)}</div>${state.cardMoves.length?`<section class="panel mt"><h2>心愿变大记录</h2>${state.cardMoves.slice(0,10).map(m=>`<div class="record-row"><div class="record-main"><strong>${m.kind==='merge'?'✨ 小卡合成大卡':'🌈 万能卡转换'}</strong><small>${time(m.created)} · 额度不增不减</small></div><strong>¥${yuan(m.face_cents)}</strong></div>`).join('')}</section>`:''}`;}
const bonusReward=b=>b.kind==='coins'?`${b.amount} ${cn()}`:`${b.amount} 次免费抽奖`;
function dailyBonusPanel(){if(state.space.status!=='active')return '';const b=state.dailyBonus;if(b.kind==='none')return '';return `<div class="daily-bonus-line"><span>${b.active?'🎉 全勤奖励已到账':'🎀 全部完成，再得'} <strong>${bonusReward(b)}</strong>${state.ticketBalance<0?' · 待补 '+(-state.ticketBalance)+' 次':''}</span><div>${state.space.isSelf&&b.eligible&&!b.active?'<button class="text-btn" data-action="claim-bonus">收下奖励</button>':b.active&&b.kind==='ticket'&&state.space.isSelf?'<button class="text-btn" data-page="lucky">去抽一次</button>':''}<button class="text-btn" data-action="bonus-help" aria-label="全勤奖励说明">说明</button></div></div>`;}
function bonusHelp(){openDialog('全勤的小惊喜，怎样领取？',`<div class="help-steps"><section><h3>🎀 完成今天的全部计划</h3><p>每间奖励小屋每天一份，最后一项打勾时自动到账。至少有 1 个今日计划；未来计划和以前已完成的单次计划不计算。</p></section><section><h3>🎟 免费机会可以攒起来</h3><p>在本小屋的幸运时刻使用，每抽一次消耗 1 次机会，不扣学习币，也不占学习币抽奖的每日次数。抽到“下次好运”仍会消耗这次机会。</p></section><section><h3>🌱 点错了，也可以重新来</h3><p>撤销或增加未完成的今日任务，会重新计算全勤；不再全勤时收回额外奖励。重新全勤只恢复原来那一份。若机会已经用掉，会记为待补次数，之后的机会先补齐。</p><p>归档后按剩余今日清单计算。当天已经发过的全勤奖励保留原类型和数量，调整规则不会改写它；新的全勤日使用新规则。</p></section></div><button class="btn full-width mt" data-action="close">知道啦，继续种小计划</button>`);}
function updateBonusForm(){const kind=$('#f-dailyBonusKind')?.value,input=$('#f-dailyBonusAmount');if(!input)return;input.disabled=kind==='none';input.max=kind==='ticket'?10:1000;if(Number(input.value)>Number(input.max)||Number(input.value)<1)input.value=1;$('#bonus-setting-hint').textContent=kind==='none'?'暂时关闭新的全勤奖励，已经领取的仍按原约定。':kind==='coins'?'每次全勤额外发放的学习币，独立于任务每日奖励上限。':'每次全勤赠送的抽奖次数，每天可赠 1–10 次，机会可以累积。';}
function luckyPage(){if(isPersonalRewardView())return rewardRoomPicker();const p=state.pool,available=Math.max(0,state.ticketBalance);return `<div class="compact-heading"><h1>幸运时刻</h1><button class="text-btn" data-action="bonus-help">机会怎么来？</button></div><section class="lucky-machine compact-machine"><div class="reel-heading"><strong>🎁 心愿转转屋</strong><div><button class="reel-arrow" data-action="reel" data-step="-1" aria-label="向左看奖品">‹</button><span>滑动看看奖品</span><button class="reel-arrow" data-action="reel" data-step="1" aria-label="向右看奖品">›</button></div></div><div class="prize-reel" tabindex="0" aria-label="可左右滑动的抽奖卡片">${[...p.slice(1),p[0]].map(x=>`<div class="reel-card ${esc(x.tone||'mint')}"><span>${esc(x.emoji)}</span><strong>${esc(x.title)}</strong><small>${x.face_cents?'¥'+yuan(x.face_cents)+' 额度':'小云朵打了个盹'} · ${(x.probability*100).toFixed(2)}%</small></div>`).join('')}</div><div class="draw-choices"><div><strong>🎟 免费机会 ${available} 次</strong><button class="btn full-width" data-action="draw" data-mode="ticket" ${!state.space.isSelf||p.length<2||available<1||state.balance<0?'disabled':''}>用 1 次免费机会</button><small>${state.ticketBalance<0?'还有 '+(-state.ticketBalance)+' 次待补':'不扣学习币，可累积'}</small></div><div><strong>✳ ${state.settings.drawCost} ${cn()} / 次</strong><button class="btn secondary full-width" data-action="draw" data-mode="coins" ${!state.space.isSelf||p.length<2||state.balance<state.settings.drawCost*UNIT||state.drawCount>=state.settings.drawLimit?'disabled':''}>用学习币抽一次</button><small>今日 ${state.drawCount} / ${state.settings.drawLimit} 次</small></div></div><p class="draw-footnote">每次独立抽取，未中奖也会消耗所选的币或机会。${p.length<2?'奖池还在准备中，机会先替你存好。':''}</p></section><details class="panel odds-details"><summary>完整奖池与概率 <span>${p.length-1} 张心愿卡 · 下次好运 ${(p[0].probability*100).toFixed(2)}%</span></summary><div class="odds-scroll">${p.map(x=>`<div class="record-row"><span class="record-icon">${esc(x.emoji)}</span><div class="record-main"><strong>${esc(x.title)}</strong><small>${x.face_cents?'¥'+yuan(x.face_cents)+' · 剩余 '+x.stock+' 张':''}</small></div><b>${(x.probability*100).toFixed(2)}%</b></div>`).join('')}</div><p class="subtext">两种抽法共用奖池。${state.settings.fixedOdds?'某张卡缺货或下架后，其概率转为下次好运。':'当前按可用库存与权重计算概率。'}</p></details>`;}

const lessons=[
  ['money','🪙','学习币是什么？','从一枚学习币，认识货币的作用。','<p>在这里，学习币记录了你的努力，也是一种<strong>大家约定接受的计价单位</strong>：完成任务得到它，用它兑换奖品。</p><p>它与人民币不同：不能充值、不能提现，也不能离开这个平台使用。它不是加密货币，更不是一份投资承诺。</p><p>如果人人都能无条件创造很多学习币，而奖品没有增加，原来的币就可能买不到同样多的东西。这可以帮助理解货币供给与购买力，但现实中的通货膨胀还受到许多因素影响。</p>'],
  ['ledger','📒','为什么需要一本账？','余额不是凭空改变的，每一步都有记录。','<p>你的余额等于：<strong>所有收入减去所有支出</strong>。任务奖励、商城兑换、抽奖花费，都分别留下记录。</p><p>取消任务时，不会偷偷抹掉原来的奖励，而是增加一笔等额的负数记录，叫做<strong>冲正</strong>。这样你可以看清来龙去脉。</p><p>如果奖励已花掉，撤销后可以出现待补余额。之后完成计划会补足它；补足之前无法继续消费或领取奖品。</p>'],
  ['risk','🌦️','概率不是承诺','10% 的概率，不代表抽十次一定中奖。','<p>假设每一次中奖率是 10%，每次抽奖又彼此独立，连续十次都没中的概率是 <strong>0.9 的十次方，约 34.9%</strong>。</p><p>之前没中奖，不会自动让下一次更容易中奖。在本站，剩余库存改变会影响奖池比例，页面会显示新的概率。</p><p>确定想要某一份奖品时，可以选择直接兑换。抽奖是体验随机惊喜的方式，花费也要计入自己的计划。</p>'],
  ['blockchain','🔗','账本与区块链','“有虚拟币”并不等于“使用区块链”。','<p>本站由服务器保存账本，属于<strong>中心化系统</strong>。平台服务与数据库负责维护记录，学习币没有上链。</p><p>区块链通常将交易打包成区块，使用密码学哈希连接，并通过共识规则让多个参与者对记录达成一致。不同区块链的具体规则并不相同。</p><p>区块链不能保证资产价格上涨，也不能保证每个链上的项目都可信。理解技术机制和判断投资风险是两件事。</p>']
];
function growthPage(){const earned=state.earnedTotal/UNIT,threshold=state.settings.marketThreshold,reached=earned>=threshold;return `<div class="growth-utilities panel"><button class="btn secondary" data-action="diary-open">📖 我的每日小日记</button><button class="text-btn" data-page="logs">📒 小屋操作日志</button><button class="text-btn" data-page="inbox">✉ 信箱与好友</button></div>${heading('GROW YOUR MIND, GROW YOUR WORLD','成长，不只多一点学习币。','一边坚持自己的计划，一边慢慢理解财富、概率和世界。')}<section class="growth-hero"><span class="lock-illustration">${reached?'🌳':'🌱'}</span><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>${reached?'你已经达成市场解锁门槛！':'为未来的模拟市场，存一点经验。'}</h2><p>累计通过完成任务获得 ${threshold} 枚${cn()}，达成模拟市场解锁门槛。花费学习币不影响进度，撤销任务会同步扣减。</p><progress class="progress" max="${threshold}" value="${Math.min(earned,threshold)}"></progress><div class="progress-label"><span>累计 ${coins(state.earnedTotal)} 枚</span><span>${reached?'门槛已达成':'还差 '+Math.max(0,threshold-earned)+' 枚'}</span></div><span class="growth-label">A 股 · ETF · 比特币 · 后续版本开放</span><p class="mt">当前版本尚未开放交易。先把每一天过好，新的体验会慢慢长出来。</p></section><div class="growth-header"><h2>小小知识，慢慢积累</h2><small>已读 ${state.lessons.length} / ${lessons.length}</small></div><div class="lesson-grid">${lessons.map(([id,emoji,title,sub])=>`<button class="lesson" data-action="lesson" data-id="${id}"><span class="lesson-emoji">${emoji}</span><span><strong>${title}</strong><p>${sub}</p></span>${icon(state.lessons.includes(id)?'check':'chevron')}</button>`).join('')}</div>`;}

function ledgerPage(){return `${heading('EVERY LITTLE EFFORT COUNTS',`每一枚${cn()}，都有来处。`,'收入、消费与撤销，都会认真记下来。',state.space.isSelf?`<a class="btn secondary" href="./api/export?space=${encodeURIComponent(state.space.id)}" download>导出账本</a>`:'')}<section class="panel">${state.ledger.map(l=>`<div class="record-row"><span class="record-icon">${icon(l.amount>0?'check':'history')}</span><div class="record-main"><strong>${esc(l.note)}</strong><small>${time(l.created)}</small></div><span class="record-amount ${l.amount>0?'positive':'negative'}">${l.amount>0?'+':''}${coins(l.amount)}</span></div>`).join('')||empty('📒','第一笔努力，还在路上','完成一个小计划，就有第一笔收入。')}</section>${state.ticketLedger.length?`<section class="panel mt"><h2>🎟 免费抽奖机会账本</h2><p class="subtext">${state.ticketBalance<0?'待补 '+(-state.ticketBalance):'可用 '+state.ticketBalance} 次 · 只在这间小屋使用</p>${state.ticketLedger.map(l=>`<div class="record-row"><div class="record-main"><strong>${esc(l.note)}</strong><small>${time(l.created)}</small></div><span class="record-amount ${l.amount>0?'positive':'negative'}">${l.amount>0?'+':''}${l.amount} 次</span></div>`).join('')}</section>`:''}`;}
let adminCategory='all';
function prizeAdmin(){const prizes=state.admin.prizes.filter(p=>adminCategory==='all'||p.category===adminCategory),defaults=state.admin.prizes.filter(p=>p.template_id);return `<section class="panel"><div class="panel-heading"><div><h2>这间小屋的心愿卡</h2><p>日常小奖，从 ¥2 起；已有卡片仍按原约定兑现。</p></div><button class="btn sm" data-action="prize">＋ 自定义</button></div><div class="reward-tools"><button class="btn sm" data-action="default-pack">🌷 一键摆好默认卡</button><button class="btn secondary sm" data-action="templates">自己挑几张</button><button class="text-btn" data-action="remove-defaults" ${!defaults.length?'disabled':''}>移除默认卡（${defaults.length}）</button></div>${!state.admin.prizes.length?'<div class="starter-prices"><strong>今天的努力，今天就够得着</strong><p>¥5 学习卡 · 25 币　/　¥10 运动卡 · 80 币　/　¥5 吃喝卡 · 100 币</p><small>以上是默认建议价，实际按本小屋比例计算，发奖人随时可改。</small></div>':''}${filterChips(adminCategory,'admin-category',[['all','全部'],...state.categories.map(c=>[c.id,c.emoji+' '+c.name])])}<div class="prize-admin-list">${prizes.map(p=>`<div class="record-row"><span class="record-icon ${p.tone}">${esc(p.emoji)}</span><div class="record-main"><strong>${esc(p.title)} ${p.face_cents?'· ¥'+yuan(p.face_cents):''}</strong><small>${coins(p.cost)} 币 · 余 ${p.stock} 张 · ${p.active?'上架':'下架'}${p.template_id?' · 默认卡':''}</small></div><div class="reward-row-actions"><button class="btn secondary sm" data-action="prize" data-id="${p.id}">编辑</button><button class="text-btn remove-link" data-action="remove-prize" data-id="${p.id}">移除</button></div></div>`).join('')||'<p class="subtext mt">这里还没有心愿卡，挑几张就能开张啦。</p>'}</div>${state.admin.removedPrizes.length?`<details class="removed-prizes"><summary>已移除 · ${state.admin.removedPrizes.length} 张（可恢复）</summary><div class="prize-admin-list">${state.admin.removedPrizes.map(p=>`<div class="record-row"><div class="record-main"><strong>${esc(p.emoji)} ${esc(p.title)}</strong><small>售价与剩余库存保留</small></div><button class="text-btn" data-action="restore-prize" data-id="${p.id}">恢复</button></div>`).join('')}</div></details>`:''}</section>`;}
function oddsAdmin(){const o=state.admin.odds;return `<section class="panel"><h2>每张卡，多少机会遇见？</h2><p class="subtext">直接填百分比，0 表示不入奖池。保存后，缺货或下架的概率转到“下次好运”，其他卡不变。</p><form id="odds-form" class="mt"><div class="odds-summary"><strong id="odds-total"></strong><span id="odds-blank"></span></div><div class="reward-tools"><button type="button" class="btn secondary sm" data-action="odds-suggest">推荐分配：卡片共 70%</button><button type="button" class="text-btn" data-action="refresh-odds">重新加载奖池</button></div><div class="odds-edit-list">${o.entries.map(e=>{const p=state.admin.prizes.find(p=>p.id===e.id);return `<div class="record-row"><span class="record-icon ${p.tone}">${esc(p.emoji)}</span><div class="record-main"><label for="odds-${e.id}"><strong>${esc(p.title)}</strong></label><small>¥${yuan(p.face_cents)} · ${p.stock?'剩 '+p.stock+' 张':'已兑完，暂归未中奖'}</small></div><div class="odds-input"><input id="odds-${e.id}" name="odds_${e.id}" data-prize="${e.id}" value="${e.bps/100}" type="number" min="0" max="100" step="0.01" required aria-label="${esc(p.title)}中奖率"><span>%</span></div></div>`;}).join('')||'<p class="subtext">先上架几张心愿卡，再来分配概率吧。</p>'}</div><p class="subtext mt">保存后，新增或恢复的卡需在这里分配概率才加入奖池。已经抽到的卡不受影响。</p>${errorSlot}<button class="btn mt" type="submit" ${o.entries.length?'':'disabled'}>保存中奖率</button></form></section>`;}
function updateOddsForm(){const inputs=[...document.querySelectorAll('#odds-form input[data-prize]')];if(!$('#odds-total'))return;const total=inputs.reduce((n,e)=>n+Math.round(Number(e.value)*100),0);$('#odds-total').textContent=`卡片合计 ${(total/100).toFixed(2)}%`;$('#odds-blank').textContent=total>10000?'超过 100% 啦，请调小一点':`下次好运 ${((10000-total)/100).toFixed(2)}%`;$('#odds-blank').classList.toggle('negative',total>10000);}
function suggestedOdds(){const rows=state.admin.odds.entries.map(e=>{const p=state.admin.prizes.find(p=>p.id===e.id);return {...e,weight:p.stock>0?(state.templates.find(t=>t.template_id===p.template_id)?.weight||(p.face_cents<=1000?20:p.face_cents<=3000?8:p.face_cents<=10000?3:1)):0};}),sum=rows.reduce((n,e)=>n+e.weight,0);let remaining=sum?7000:0;for(const e of rows){e.bps=sum?Math.floor(e.weight/sum*7000):0;remaining-=e.bps;}for(const e of rows)if(e.weight&&remaining-->0)e.bps++;for(const e of rows)$('#odds-'+e.id).value=e.bps/100;updateOddsForm();dirty=true;}
function templatesDialog(){openDialog('挑几张可爱卡，今天就有小盼头',`<form id="templates-form"><p class="subtext">每款默认 3 张。重复添加不会多出卡，也不会补回用掉的库存。</p><div class="template-categories">${state.categories.filter(c=>state.templates.some(t=>t.category===c.id)).map((c,i)=>`<details ${i===0?'open':''}><summary>${c.emoji} ${c.name}</summary>${state.templates.filter(t=>t.category===c.id).sort((a,b)=>a.face_cents-b.face_cents).map(t=>`<label class="merge-option"><input type="checkbox" name="templates" value="${t.template_id}"><span>${esc(t.emoji)}</span><div><strong>${esc(t.title)}</strong><small>${Math.ceil(t.face_cents*state.settings.rates[t.category]/100)} 学习币 · ${esc(t.tier)}</small></div><b>¥${yuan(t.face_cents)}</b></label>`).join('')}</details>`).join('')}</div>${actions('摆好选中的卡')}</form>`);}
function removePrizeDialog(ids){openDialog('把这些心愿卡先收起来？',`<p>将移除 ${ids.length} 张商品。朋友已经拿到的卡仍可兑现，剩余库存和价格也会保留。</p><p class="subtext">之后可以从“已移除”里恢复。</p><form id="remove-prizes-form" data-ids="${ids.join(',')}">${actions('确认移除')}</form>`);}

function adminPage(){if(!state.admin)return empty('🌿','这里是发奖小桌','这间小屋的发奖人可以在这里准备奖励。');const s=state.settings;let content='';if(adminTab==='prizes')content=prizeAdmin();
if(adminTab==='odds')content=oddsAdmin();

if(adminTab==='redemptions')content=`<section class="panel"><h2>先完成报销，再核销卡片</h2>${state.admin.redemptions.map(c=>`<div class="record-row"><span class="record-icon">${esc(c.emoji)}</span><div class="record-main"><strong>${esc(c.title)} · ¥${yuan(c.claim_cents)}</strong><small>${esc(c.name||state.space.name)}</small><small>${c.status==='fulfilled'?'已核销 · '+esc(c.delivery_note):esc(c.receipt_note)}</small></div><button class="btn ${c.status==='fulfilled'?'secondary ':''}sm" data-action="fulfill" data-id="${c.id}">${c.status==='fulfilled'?'查看记录':'确认报销'}</button></div>`).join('')||empty('📮','没有待处理的申请','对方提交购买或充值记录后，会出现在这里。')}</section>`;
if(adminTab==='settings')content=`<section class="panel"><h2>这间小屋的约定</h2><form id="settings-form" class="mt"><div class="admin-grid"><div>${field('空间名','spaceName','text',s.spaceName,'required maxlength="24"')}${field('积分名字','coinName','text',s.coinName,'required maxlength="12"')}${field('每日赚币上限','dailyCap','number',s.dailyCap,'required min="1" max="1000"')}${field('市场累计解锁门槛（交易未开放）','marketThreshold','number',s.marketThreshold,'required min="1" max="100000"')}</div><div>${field('抽奖花费','drawCost','number',s.drawCost,'required min="1" max="10000"')}${field('每日学习币抽奖次数','drawLimit','number',s.drawLimit,'required min="1" max="50"')}<p class="subtext">每张卡的中奖率，在「抽奖概率」里单独设置。</p></div></div><div class="bonus-settings"><h3>🎀 今日全勤，再多一份小奖励</h3><p class="subtext">完成全部今日计划后自动获得。每天一份，各间小屋单独计算。</p><div class="form-row mt">${select('全勤送什么？','dailyBonusKind',[['ticket','免费抽奖机会'],['coins','额外学习币'],['none','暂时关闭']],s.dailyBonusKind)}${field('每次送多少','dailyBonusAmount','number',s.dailyBonusAmount,s.dailyBonusKind==='none'?'disabled':'required min="1" max="'+(s.dailyBonusKind==='ticket'?10:1000)+'"')}</div><p id="bonus-setting-hint" class="subtext">${s.dailyBonusKind==='coins'?'额外学习币独立于任务每日奖励上限。':s.dailyBonusKind==='none'?'新的全勤奖励暂时关闭，已经领取的保留。':'免费机会可以累积，不占学习币抽奖的每日次数。'}</p><p class="subtext">今日已经发过的奖励按原类型和数量恢复，修改不会重复发放。</p></div><h3>每 ¥1 报销额度，需要多少学习币？</h3><p class="subtext">学习最优惠，其次运动、衣鞋包、首饰香水、吃喝。这里改变的是新卡建议价，已有商品售价不会悄悄改变；编辑商品时可按新比例重新计算。</p><div class="rate-grid mt">${state.categories.map(c=>field(c.emoji+' '+c.name,'rate_'+c.id,'number',s.rates[c.id],'required min="1" max="1000"')).join('')}</div>${errorSlot}<button class="btn" type="submit">保存这份约定</button></form></section>`;return `<div class="compact-heading"><h1>${state.family?'家庭奖品小桌':'给 '+esc(state.space.name)+' 准备奖励'}</h1></div><div class="admin-tabs">${(state.space.status!=='active'?[['redemptions','旧卡报销']]:[['prizes','心愿卡'],['odds','抽奖概率'],['redemptions','报销核销'],['settings','小屋规则']]).map(([t,n])=>`<button class="${adminTab===t?'active':''}" data-action="admin-tab" data-value="${t}">${n}</button>`).join('')}</div>${content}`;}
function taskDialog(){openDialog('种下一个小计划',`<form id="task-form">${field('想完成什么？','title','text','','required maxlength="100" placeholder="例如：背 20 个四级单词"')}<div class="form-row">${select('分类','category',['学习','运动','生活','工作'].map(s=>[s,s]),'学习')}${field('奖励学习币','points','number',20,'required min="1" max="100"')}</div>${select('普通计划或四象限','quadrant',QUADRANTS,'none')}<div class="form-row">${select('重复方式','recurrence',[['once','只做一次'],['daily','每天重复']],'once')}${field('开始日期','start_date','date',state.day,`required min="${state.day}"`)}</div>${actions('种下这个小计划')}</form>`);}
function importDialog(){imported=[];openDialog('把一段计划，种进今天',`<form id="import-form">${textarea('粘贴 Markdown 或普通清单','markdown','','placeholder="### 紧急 & 重要&#10;- [ ] C 语言作业&#10;&#10;### 不紧急 & 重要&#10;[ ] 背四级单词"')}<div class="import-options"><label class="file-pick">也可以上传文件<input id="import-file" type="file" accept=".md,.markdown,.txt,.csv,.json"></label><button type="button" class="btn secondary sm" data-action="preview-import">解析并预览</button></div><div class="form-row mt">${field('每项默认奖励','import_points','number',20,'min="1" max="100" required')}${select('重复方式','import_recurrence',[['once','只做一次'],['daily','每天重复']],'once')}</div><p class="subtext">支持 - [ ]、[ ]、普通列表和四象限标题。已勾选的 [x] 项会作为待办导入，不自动发币。最多 50 项。</p><div id="import-preview"></div>${actions('确认导入')}</form>`);}
function parseCsv(text){const rows=[],row=[];let cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(cell);cell='';}else if(/[\r\n]/.test(c)&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push([...row]);row.length=0;cell='';}else cell+=c;}if(quote)throw new Error('CSV 引号没有闭合');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function previewImport(text,name='plans.md'){const opts={points:Number($('#f-import_points').value),recurrence:$('#f-import_recurrence').value,start_date:state.day};let checked=0;if(/\.json$/i.test(name)){let data=JSON.parse(text);imported=Array.isArray(data)?data:data.tasks;}else if(/\.csv$/i.test(name)){const rows=parseCsv(text.replace(/^\uFEFF/,''));if(['title','任务','任务名称'].includes(rows[0]?.[0]?.trim()))rows.shift();imported=rows.map(([title,points,recurrence,category,start_date,quadrant])=>({title,points:Number(points||opts.points),recurrence:['daily','每天','每日'].includes(recurrence)?'daily':'once',category:category||'学习',start_date:start_date||state.day,quadrant:quadrant||'none'}));}else{const parsed=parseMarkdown(text,opts);imported=parsed.tasks;checked=parsed.checked;}if(!Array.isArray(imported)||!imported.length||imported.length>50)throw new Error('请准备 1–50 个计划');imported=imported.map(t=>({...opts,category:'学习',quadrant:'none',...t,points:Number(t.points??opts.points)}));$('#import-preview').innerHTML=`<p class="subtext mt">解析到 ${imported.length} 个小计划${checked?'；其中 '+checked+' 个已勾选项将作为待办导入':''}。</p><div class="import-preview">${imported.map(t=>`<div class="record-row"><div class="record-main"><strong>${esc(t.title)}</strong><small>${qname(t.quadrant)} · ${t.recurrence==='daily'?'每天':'单次'}</small></div><strong>+${t.points}</strong></div>`).join('')}</div>`;}
function prizeDialog(pid){const p=state.admin.prizes.find(p=>p.id===pid)||{title:'',description:'凭购买或充值记录，在卡片额度内报销。',emoji:'🌷',tone:'mint',cost:50*UNIT,face_cents:1000,category:'study',tier:'小小补给',stock:3,weight:5,wait_days:0,active:1};openDialog(pid?'修改这份小心愿':'定制一张心愿卡',`<form id="prize-form" data-id="${pid||''}">${field('卡片名字','title','text',p.title,'required maxlength="50" placeholder="例如：灵感充电卡"')}<div class="form-row">${select('品类','category',state.categories.map(c=>[c.id,c.emoji+' '+c.name]),p.category)}${field('人民币额度（元）','face','number',p.face_cents/100,'required min="0" max="10000" step="0.01"')}</div>${field('等级名字','tier','text',p.tier,'required maxlength="24"')}${textarea('适用内容 / 报销约定','description',p.description,'required maxlength="300"')}<div class="form-row">${field('可爱图标','emoji','text',p.emoji,'required maxlength="12"')}${select('卡片颜色','tone',[['mint','薄荷绿'],['peach','奶杏桃'],['lilac','香芋紫'],['yellow','奶油黄'],['sky','晴空蓝'],['rainbow','彩虹云']],p.tone)}</div><p id="price-hint" class="subtext"></p><button type="button" class="text-btn" data-action="price-suggest">使用建议价</button><div class="form-row">${field('购买价（学习币）','cost','number',p.cost/UNIT,'required min="1" max="1000000"')}${field('还可发几张','stock','number',p.stock,'required min="0" max="10000"')}</div><div class="form-row"><p class="subtext">抽奖中奖率在「抽奖概率」里按百分比设置。</p>${field('获得后等待几天可报销','wait_days','number',p.wait_days,'required min="0" max="365"')}</div><label class="checkbox-label"><input name="active" type="checkbox" ${p.active?'checked':''}> 上架到这个配对的商城</label><p class="subtext">特别约定可填 0 元，表示不按金额的实物奖励。已发出的卡片不会随编辑改变。</p>${actions('保存心愿卡')}</form>`);updatePrice();}
function updatePrice(){if(!$('#prize-form'))return;const rate=state.settings.rates[$('#f-category').value]||10,price=Math.ceil(Number($('#f-face').value)*rate);$('#price-hint').textContent=`当前建议价：每 ¥1 = ${rate} 学习币，这张卡约 ${price} 币。`;} 
function profileDialog(){const u=state.user;openDialog('我的小屋与伙伴',`<div class="record-row"><span class="avatar">${esc(u.name.slice(0,1))}</span><div class="record-main"><strong>${esc(u.name)}</strong><small>@${esc(u.username)}</small></div></div><p class="subtext">和一个朋友建双人小屋，或成立最多六人的家庭。不同小屋互不影响，日记只给自己看。</p><div class="welcome-links"><button class="text-btn" data-page="inbox">✉ 我的信箱与好友</button><button class="text-btn" data-action="diary-open">📖 我的日记</button><button class="text-btn" data-action="room-settings">⚙ 当前小屋设置</button></div><div class="room-list">${state.rooms.map(r=>`<button class="room-link ${r.id===state.space.id?'current':''}" data-action="switch-room" data-id="${r.id}"><span>${esc(roomLabel(r))}</span><small>${r.family_id?'家庭成员可看计划':!r.giver_id?'只有自己能看':r.learner_id===u.id?'发奖人 @'+esc(r.giver_username):'领奖人 @'+esc(r.learner_username)}</small></button>`).join('')}</div><div class="pair-actions"><button class="btn" data-action="family-create">🏡 成立一个家庭</button><button class="btn secondary" data-action="invite" data-direction="manager">🎁 邀请朋友给我发奖</button><button class="btn secondary" data-action="invite" data-direction="learner">💌 邀请朋友来我这领奖</button><button class="btn secondary" data-action="accept-invite">我有邀请码</button></div>${state.archivedRooms.length?'<details class="mt"><summary>历史小屋 · '+state.archivedRooms.length+'</summary><div class="room-list">'+state.archivedRooms.map(r=>'<button class="room-link" data-action="switch-room" data-id="'+r.id+'"><span>'+esc(roomLabel(r))+'</span><small>'+'已关闭 · 保留历史和旧卡'+'</small></button>').join('')+'</div></details>':''}<div class="welcome-links"><button class="text-btn" data-action="help">看看怎么玩</button><button class="text-btn" data-action="install">放到手机桌面</button>${status.apkAvailable?'<a class="text-btn" href="./downloads/starlight.apk" download>安卓 App</a>':''}</div>${state.demo?'<div class="pair-box"><small>切换示例人物</small><button class="text-btn" data-action="demo-role" data-username="demo">小凡</button><button class="text-btn" data-action="demo-role" data-username="seedling">小芽</button><button class="text-btn" data-action="demo-role" data-username="sunshine">晴天</button></div>':''}${state.emailEnabled?'<div class="identity-box"><p>邮箱：'+esc(u.email||'尚未绑定')+'</p><button class="text-btn" data-action="bind-email">绑定 / 更换邮箱</button></div>':''}${state.githubEnabled?'<div class="identity-box"><p>GitHub：'+esc(u.github_login||'尚未绑定')+'</p><button class="text-btn" data-action="github">绑定 GitHub</button></div>':''}<div class="form-actions"><button class="btn secondary sm" data-action="password">修改密码</button><button class="btn secondary sm" data-action="logout">退出登录</button></div>`);}

function redeemDialog(c){openDialog('让这份心愿，变成真的快乐',`<div class="mini-wish ${c.tone}"><span>${esc(c.emoji)}</span><div><h3>${esc(c.title)}</h3><p>${c.face_cents?'最高报销 ¥'+yuan(c.face_cents):'按约定兑现'}</p></div></div><form id="redeem-form" data-id="${c.id}">${c.face_cents?field('本次申请报销金额（元）','claim','number',c.face_cents/100,`required min="0.01" max="${c.face_cents/100}" step="0.01"`):''}${textarea('买了什么 / 充值记录','receipt_note','','maxlength="1000" '+(c.face_cents?'required':'')+' placeholder="例如：10 月 26 日 AI API 充值，金额 20 元。可附截图，也可以线下给发奖人看记录。"')}<div class="field"><label for="receipt-file">附一张凭证（可选，3 MB 内）</label><input id="receipt-file" type="file" accept="image/png,image/jpeg,image/webp"></div><p class="subtext">提交后生成核销链接，分享给对应发奖人。对方在现实中完成报销后再确认；核销整张卡，未使用的额度不会返还。</p>${actions('提交并生成核销链接')}</form>`);}
function shareDialog(r){const url=location.origin+location.pathname+'#redeem='+r.token;openDialog('把这份心愿，递给支持你的人',`<p>链接有效 14 天，仅对应发奖人登录后可查看。打开不会自动核销；对方确认已报销后，这张卡才会核销。</p><div class="field"><label for="share-url">核销链接</label><input id="share-url" value="${esc(url)}" readonly></div><button class="btn full-width" data-action="copy-share">复制分享链接</button><p class="subtext mt">重新生成会让旧链接失效。</p>`);}
function fulfillDialog(c,token=''){openDialog(c.status==='fulfilled'?'这份心愿已经兑现':'确认这份报销已经完成',`<div class="mini-wish ${c.tone}"><span>${esc(c.emoji)}</span><div><h3>${esc(c.title)}</h3><p>${esc(c.name||state.space.name)} · 申请 ¥${yuan(c.claim_cents)}</p></div></div><p class="receipt-note">${esc(c.receipt_note||'按双方的实物约定发放。')}</p>${c.has_receipt?`<a href="./api/receipts/${c.id}" target="_blank" rel="noopener"><img class="receipt-preview" src="./api/receipts/${c.id}" alt="购买或充值凭证"></a>`:''}${c.status==='fulfilled'?`<p>已报销 ¥${yuan(c.paid_cents)} · ${esc(c.delivery_note)}</p><button class="btn full-width" data-action="close">知道了</button>`:`<form id="fulfill-form" data-id="${c.id}" data-token="${esc(token)}" data-version="${c.redemption_version}">${c.face_cents?field('实际已报销金额（元）','paid','number',c.claim_cents/100,`required min="0.01" max="${c.claim_cents/100}" step="0.01"`):''}${field('报销 / 发放说明','note','text','','required maxlength="200" placeholder="例如：已转账报销，或已代充值完成"')}<label class="checkbox-label"><input type="checkbox" required> 我已在现实中完成报销或发放</label>${actions('确认已报销，核销此卡')}</form>`}`);}
function mergeDialog(){const cards=state.cards.filter(c=>c.status==='ready'&&c.face_cents>0);openDialog('小小心愿，合成大大的快乐',`<form id="merge-form"><p class="subtext">选择至少两张同品类卡。额度相加，不额外花学习币；新卡继承最晚可用日期。</p><div class="merge-list">${cards.map(c=>`<label class="merge-option"><input name="cards" type="checkbox" value="${c.id}"><span>${esc(c.emoji)}</span><div><strong>${esc(c.title)}</strong><small>${category(c.category).name} · ${date(c.available)} 可用</small></div><b>¥${yuan(c.face_cents)}</b></label>`).join('')||'<p>还没有可合成的额度卡。</p>'}</div><p id="merge-total" class="subtext mt">已选 0 张 · 合计 ¥0</p>${field('给新卡起个可爱名字（选填）','title','text','','maxlength="50" placeholder="留空自动按品类命名"')}${actions('合成一张大心愿')}</form>`);}
async function mutation(route,body,message,key){const r=await api(route,body,{key});dialog.close();await refresh();if(r.bonus){const reward=bonusReward({kind:r.bonus.kind,amount:Math.abs(r.bonus.amount)});toast(r.bonus.amount>0?`${r.bonus.restored?'全勤奖励恢复啦':'今日全勤达成啦'} ✨ ${reward}`:`全勤奖励暂时收回 ${reward}，全部完成后恢复`);}else if(message)toast(message);return r;}
async function receiptFile(){const file=$('#receipt-file')?.files[0];if(!file)return undefined;if(file.size>3*1024*1024)throw new Error('凭证请控制在 3 MB 内');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});return {mime:file.type,data};}
document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;if(el.dataset.page){event.preventDefault();page=el.dataset.page;dialog.close();try{if(state.family&&state.space.id!==state.family.mySpace&&['shop','cards','lucky'].includes(page)){space=state.family.mySpace;await refresh();}else{await community.load(page);render();}}catch(e){toast(e.message);}scrollTo({top:0});return;}const action=el.dataset.action;if(!action)return;event.preventDefault();if(action==='close'){dialog.close();return;}if(busy)return;
try{if(action.startsWith('family-')||action.startsWith('mail-')||action.startsWith('friend-')||['room-settings','close-request','close-cancel','pending-mail','day-share','share-revoke','diary-open','diary-load','logs-more'].includes(action))busy=true;switch(action){
case 'reload':await boot();break;
case 'auth-mode':authMode=el.dataset.mode;emailChallenge='';renderAuth();break;
case 'demo':busy=true;await api('demo',{});await boot();break;
case 'demo-role':busy=true;await api('demo',{username:el.dataset.username});space='';page='today';dialog.close();await boot();break;
case 'task':taskDialog();break;
case 'task-filter':taskFilter=el.dataset.value;render();break;
case 'task-view':taskView=el.dataset.value;render();break;
case 'shop-filter':shopFilter=el.dataset.value;render();break;
case 'card-filter':cardFilter=el.dataset.value;render();break;
case 'admin-tab':adminTab=el.dataset.value;render();if(adminTab==='settings')updateBonusForm();if(adminTab==='odds')updateOddsForm();break;
case 'profile':profileDialog();break;
case 'help':howTo();break;
case 'bonus-help':bonusHelp();break;
case 'bonus-settings':page='admin';adminTab='settings';render();updateBonusForm();break;
case 'claim-bonus':busy=true;await mutation('bonus/claim',{},'今天的小奖励已经收下啦');break;
case 'switch-room':space=el.dataset.id;page='today';dialog.close();await refresh();break;
case 'reward-room':space=el.dataset.id;shopFilter='all';cardFilter='ready';dialog.close();await refresh();break;
case 'logout':busy=true;await api('logout',{});state=null;space='';page='today';dialog.close();await boot();break;
case 'complete':{const t=state.tasks.find(t=>t.id===el.dataset.id);if(t.done&&(state.dailyBonus.active||state.balance<(t.awarded||t.points))){openDialog('撤销这次小完成？',`<p>将撤回 ${coins(t.awarded||t.points)} ${cn()}，不足部分记为待补余额。</p>${state.dailyBonus.active?'<p>若不再全勤，今天的额外奖励也会收回；全部完成后恢复原来那一份。已用掉的免费机会记为待补次数。</p>':''}<form id="complete-form" data-id="${t.id}" data-done="0">${actions('确认撤销')}</form>`);}else{busy=true;await mutation('complete',{task_id:t.id,done:!t.done,day:state.day},t.done?'已撤销，奖励已扣回':'小小成就已入账 ✨');}break;}
case 'note':{const t=state.tasks.find(t=>t.id===el.dataset.id);openDialog('记下一点完成的收获',`<form id="note-form" data-id="${t.id}">${textarea(esc(t.title),'note',t.note||'','maxlength="1000"')}<p class="subtext">保存会标记为已完成；已完成任务不会重复发币。</p>${actions('保存完成记录')}</form>`);break;}
case 'archive':openDialog('把这个计划收起来？',`<p>保留任务已获得的学习币和历史记录。归档后会按剩余今日清单重新计算全勤奖励。</p><form id="archive-form" data-id="${el.dataset.id}">${actions('归档计划')}</form>`);break;
case 'import':importName='plans.md';importDialog();break;
case 'preview-import':imported=[];previewImport($('#f-markdown').value,importName);break;
case 'buy':{const p=state.prizes.find(p=>p.id===el.dataset.id);openDialog('把这张小心愿，装进口袋',`<div class="mini-wish ${p.tone}"><span>${esc(p.emoji)}</span><div><h3>${esc(p.title)}</h3><p>${p.face_cents?'¥'+yuan(p.face_cents)+' 报销额度':''}</p></div></div><p>消耗 ${coins(p.cost)} ${cn()}。${p.wait_days?'获得后等待 '+p.wait_days+' 天可申请。':'获得后即可申请。'}</p><form id="buy-form" data-id="${p.id}">${actions('确认抱走')}</form>`);break;}
case 'draw':{const mode=el.dataset.mode||'coins',free=mode==='ticket';openDialog(free?'用一份全勤奖励，接住小幸运':'转一转，接住一点小幸运',`<p>${free?'消耗 1 次免费机会，不扣学习币':'花费 '+state.settings.drawCost+' '+cn()}。“下次好运”的概率是 ${(state.pool[0].probability*100).toFixed(1)}%，未中奖也会消耗${free?'这次机会':'学习币'}。</p><form id="draw-form" data-mode="${mode}">${actions(free?'使用 1 次免费机会':'确认用学习币抽一次')}</form>`);break;}

case 'redeem':redeemDialog(state.cards.find(c=>c.id===el.dataset.id));break;
case 'share':busy=true;shareDialog(await api('share',{card_id:el.dataset.id}));break;
case 'copy-share':await navigator.clipboard.writeText($('#share-url').value);toast('链接已复制，发给你的发奖人吧');break;
case 'cancel-redeem':openDialog('撤回这次报销申请？',`<p>卡片恢复待使用，旧分享链接失效。</p><form id="cancel-form" data-id="${el.dataset.id}">${actions('确认撤回')}</form>`);break;
case 'fulfill':fulfillDialog(state.admin.redemptions.find(c=>c.id===el.dataset.id));break;
case 'merge':mergeDialog();break;
case 'convert':{const c=state.cards.find(c=>c.id===el.dataset.id);openDialog('万能小云朵，变成想要的样子',`<form id="convert-form" data-id="${c.id}"><p class="subtext">可用 ¥${yuan(c.face_cents)}，按人民币额度 1:1 转换。没用完的额度保留为一张万能卡。</p>${select('想变成哪一类？','category',state.categories.filter(c=>!['universal','custom'].includes(c.id)).map(c=>[c.id,c.emoji+' '+c.name]),'study')}${field('转换额度（元）','face','number',c.face_cents/100,`required min="0.01" max="${c.face_cents/100}" step="0.01"`)}${field('新卡名字（选填）','title','text','','maxlength="50"')}${actions('变成新的心愿')}</form>`);break;}
case 'prize':prizeDialog(el.dataset.id);break;
case 'templates':templatesDialog();break;
case 'default-pack':{busy=true;const r=await mutation('admin/templates',{templates:state.templates.map(t=>t.template_id)},'');toast(r.added||r.restored?`新摆好 ${r.added} 张，恢复 ${r.restored} 张心愿卡`:'默认卡已经摆好啦，没有重复添加');break;}
case 'admin-category':adminCategory=el.dataset.value;render();break;
case 'remove-prize':removePrizeDialog([el.dataset.id]);break;
case 'remove-defaults':removePrizeDialog(state.admin.prizes.filter(p=>p.template_id).map(p=>p.id));break;
case 'restore-prize':busy=true;await mutation('admin/prizes/restore',{ids:[el.dataset.id]},'卡片恢复啦，可再检查一下抽奖概率');break;
case 'odds-suggest':suggestedOdds();break;
case 'refresh-odds':await refresh();updateOddsForm();break;
case 'price-suggest':$('#f-cost').value=Math.max(1,Math.ceil(Number($('#f-face').value)*(state.settings.rates[$('#f-category').value]||10)));dirty=true;break;
case 'reel':$('.prize-reel').scrollBy({left:Number(el.dataset.step)*$('.prize-reel').clientWidth*.75,behavior:'smooth'});break;

case 'invite':openDialog(el.dataset.direction==='manager'?'邀请朋友给我发奖':'邀请朋友来我这领奖',`<form id="invite-form" data-direction="${el.dataset.direction}"><p>${el.dataset.direction==='manager'?'你来做计划、攒币领奖，朋友来准备奖励、确认报销。':'朋友来做计划、攒币领奖，你来准备奖励、确认报销。'}</p><p class="subtext">对方确认后，你们会有一间全新的小屋。已有小屋和个人计划保持原样。</p>${field('给这份邀请留句话','label','text','一起慢慢长大','required maxlength="40"')}${actions('生成小屋邀请码')}</form>`);break;
case 'copy-invite':await navigator.clipboard.writeText($('#invite-code').textContent);toast('请柬复制好啦，发给这位朋友吧');break;
case 'copy-invite-link':await navigator.clipboard.writeText($('#invite-link').value);toast('邀请链接已复制');break;
case 'accept-invite':joinDialog();break;
case 'preview-pair':await previewInvite();break;

case 'password':openDialog('设置或修改我的密码',`<form id="password-form">${field('原密码（仅 GitHub 注册可留空）','oldPassword','password','','autocomplete="current-password"')}${field('新密码','password','password','','required minlength="10" maxlength="128" autocomplete="new-password"')}${actions('保存密码')}</form>`);break;
case 'bind-email':emailChallenge='';openDialog('绑定一个自己的邮箱',`<form id="email-form">${field('邮箱地址','email','email','','required autocomplete="email"')}<button class="btn secondary" type="button" data-action="email-send">发送验证码</button>${field('邮箱里的 6 位验证码','email_code','text','','required inputmode="numeric" pattern="[0-9]{6}"')}${actions('验证并绑定邮箱')}</form>`);break;
case 'email-send':{busy=true;const data={email:$('#f-email').value};if(!state&&pendingInvite)data.code=pendingInvite.code;const r=await api('email/start',data);emailChallenge=r.challenge;toast('验证码已发送，10 分钟内有效');break;}
case 'github':{busy=true;const r=await api('auth/github/start',{});location.assign(r.url);break;}
case 'lesson':{const l=lessons.find(l=>l[0]===el.dataset.id);openDialog(l[2],`<div class="lesson-text">${l[4]}</div>${state.space.isSelf?'<form id="lesson-form" data-id="'+l[0]+'">'+actions('我读完啦')+'</form>':''}`);break;}
case 'install':if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openDialog('把心愿花园放到手机桌面',`<p><strong>iPhone：</strong>用 Safari 打开网站，点分享按钮，再选择“添加到主屏幕”。</p><p><strong>安卓：</strong>用 Chrome 或支持安装的浏览器打开，在菜单里选择“安装应用”或“添加到主屏幕”。</p><p>之后点桌面图标就能进入。记账、抽奖和报销需要联网。</p><button class="btn full-width" data-action="close">知道啦</button>`);break;
default:await community.click(action,el);break;
}}catch(e){toast(e.message);}finally{busy=false;}});
document.addEventListener('submit',async event=>{event.preventDefault();if(busy)return;const form=event.target,formData=new FormData(form),data=Object.fromEntries(formData),button=form.querySelector('button[type="submit"]'),error=form.querySelector('.error-text');busy=true;if(button)button.disabled=true;if(error)error.textContent='';const fingerprint=JSON.stringify([[...formData].map(([k,v])=>[k,v instanceof File?[v.name,v.size,v.lastModified]:v]),event.submitter?.value]);if(form.dataset.body!==fingerprint){form.dataset.key=crypto.randomUUID();form.dataset.body=fingerprint;}const key=form.dataset.key||crypto.randomUUID();try{switch(form.id){
case 'auth-form':{await api(form.dataset.mode,data);space='';page='today';await boot();break;}
case 'task-form':await mutation('tasks',{tasks:[{...data,points:Number(data.points)}]},'小计划种下啦',key);break;
case 'complete-form':await mutation('complete',{task_id:form.dataset.id,done:form.dataset.done==='1',day:state.day},form.dataset.done==='1'?'小小成就已入账 ✨':'已撤销，奖励已扣回',key);break;
case 'note-form':await mutation('complete',{task_id:form.dataset.id,done:true,day:state.day,note:data.note},'完成记录已保存',key);break;
case 'archive-form':await mutation('archive',{task_id:form.dataset.id},'计划已归档',key);break;
case 'import-form':if(!imported.length)throw new Error('请先解析并检查预览');await mutation('tasks',{tasks:imported},`成功种下 ${imported.length} 个小计划`,key);break;
case 'buy-form':await mutation('buy',{prize_id:form.dataset.id,expectedCost:state.prizes.find(p=>p.id===form.dataset.id).cost},'新的心愿卡，装进口袋啦',key);break;
case 'draw-form':{const r=await mutation('draw',{mode:form.dataset.mode,expectedCost:state.settings.drawCost,poolVersion:state.poolVersion},'',key);openDialog(r.card?'接住这份小惊喜！':'让好运，再长一会儿',`<div class="dialog-emoji confetti">${esc(r.card?.emoji||'☘️')}</div><h3 class="big-result">${esc(r.card?.title||'下次好运')}</h3><p>${r.card?'卡片已经放进卡包，快去看看吧。':r.mode==='ticket'?'这次未中奖，已使用 1 次免费机会，没有扣学习币。':'这次未中奖，学习币已扣除。每次机会彼此独立。'}</p><button class="btn full-width" data-page="cards">看看我的卡包</button>`);break;}
case 'redeem-form':{const r=await mutation('redeem',{card_id:form.dataset.id,claim_cents:Math.round(Number(data.claim||0)*100),receipt_note:data.receipt_note,receipt:await receiptFile()},'',key);shareDialog(r);break;}
case 'cancel-form':await mutation('redeem/cancel',{card_id:form.dataset.id},'申请已撤回，旧链接失效',key);break;
case 'fulfill-form':await mutation('admin/fulfill',{card_id:form.dataset.id,note:data.note,paid_cents:Math.round(Number(data.paid||0)*100),token:form.dataset.token||undefined,expectedVersion:Number(form.dataset.version)},'已核销，记下这份快乐的兑现',key);history.replaceState(null,'',location.pathname);break;
case 'merge-form':await mutation('cards/merge',{card_ids:formData.getAll('cards'),title:data.title},'小心愿合成大心愿啦 ✨',key);break;
case 'convert-form':await mutation('cards/convert',{card_ids:[form.dataset.id],category:data.category,face_cents:Math.round(Number(data.face)*100),title:data.title},'小云朵变成新的心愿啦 🌈',key);break;
case 'prize-form':await mutation('admin/prize',{...data,id:form.dataset.id||undefined,space_id:state.space.id,expectedStock:form.dataset.id?state.admin.prizes.find(p=>p.id===form.dataset.id).stock:undefined,face_cents:Math.round(Number(data.face)*100),use_rate:data.use_rate==='on',cost:Number(data.cost),stock:Number(data.stock),weight:form.dataset.id?state.admin.prizes.find(p=>p.id===form.dataset.id).weight:5,wait_days:Number(data.wait_days),active:data.active==='on'},'这份心愿已经准备好了',key);break;
case 'templates-form':await mutation('admin/templates',{space_id:state.space.id,templates:formData.getAll('templates')},'选中的小心愿已上架',key);break;
case 'remove-prizes-form':await mutation('admin/prizes/remove',{ids:form.dataset.ids.split(',')},'心愿卡已收起，需要时可以恢复',key);break;
case 'odds-form':await mutation('admin/odds',{version:state.admin.odds.version,entries:[...form.querySelectorAll('input[data-prize]')].map(e=>({id:e.dataset.prize,bps:Math.round(Number(e.value)*100)}))},'每张卡的中奖率已保存',key);updateOddsForm();break;
case 'settings-form':{const rates=Object.fromEntries(state.categories.map(c=>[c.id,Number(data['rate_'+c.id])]));await mutation('admin/settings',{...data,rates,space_id:state.space.id,dailyCap:Number(data.dailyCap),drawCost:Number(data.drawCost),drawLimit:Number(data.drawLimit),blankWeight:state.settings.blankWeight,marketThreshold:Number(data.marketThreshold),dailyBonusAmount:Number(data.dailyBonusAmount||1)},'小屋规则已保存',key);break;}
case 'invite-form':{const r=await mutation('admin/invite',{label:data.label,direction:form.dataset.direction},'',key),url=location.origin+location.pathname+'#join='+r.code;openDialog('给朋友的一张小请柬',`<p>${r.direction==='manager'?'邀请朋友给你发奖。':'邀请朋友来你这里领奖。'}系统已生成专属邀请码，7 天内、仅一位朋友可用。</p><div id="invite-code" class="code-display">${esc(r.code.match(/.{1,6}/g).join('-'))}</div><button class="btn full-width" data-action="copy-invite">复制邀请码</button><input id="invite-link" class="sr-only" value="${esc(url)}" readonly aria-label="邀请链接"><button class="btn secondary full-width mt" data-action="copy-invite-link">复制邀请链接</button><p class="subtext mt">朋友打开链接或输入邀请码后，会先核对双方身份，再确认建屋。</p>`);break;}
case 'accept-form':{const code=readInviteCode(data.code);if(form.dataset.invitePreview!==code)throw new Error('先看一眼邀请人，再确认吧');if(!state){pendingInvite={code,preview:form._preview};history.replaceState(null,'',location.pathname+'#join='+encodeURIComponent(code));authMode='login';dialog.close();renderAuth();break;}const r=form._preview.existingSpace?{space_id:form._preview.existingSpace}:await api('pairs/accept',{code},{key});pendingInvite=null;history.replaceState(null,'',location.pathname);space=r.space_id;page='today';dialog.close();await refresh();toast(form._preview.existingSpace?'回到你们的小屋啦':'新小屋建好啦，一起种下小心愿');break;}

case 'password-form':await mutation('password',data,'密码已更新',key);break;
case 'email-form':await mutation('email/confirm',{...data,challenge:emailChallenge},'邮箱已验证，现在可以用邮箱登录',key);break;
case 'github-confirm-form':await mutation('auth/github/confirm',{pending:bindPending},'GitHub 绑定成功',key);history.replaceState(null,'',location.pathname);break;
case 'lesson-form':await mutation('lesson',{lesson:form.dataset.id},'又记下一个小知识 🌱',key);break;
default:await community.submit(form,data,formData,key,event.submitter);break;
}}catch(e){if(error&&document.contains(error))error.textContent=e.message;else toast(e.message);}finally{busy=false;if(button)button.disabled=false;}});
document.addEventListener('change',async e=>{try{if(e.target.id==='f-dailyBonusKind')updateBonusForm();if(e.target.id==='space-select'){space=e.target.value;page='today';await refresh();}if(e.target.id==='import-file'){const f=e.target.files[0];if(f){if(f.size>256*1024)throw new Error('文件不能超过 256 KB');imported=[];const text=await f.text();$('#f-markdown').value=text;importName=f.name;previewImport(text,importName);}}if(e.target.closest('#merge-form')){const ids=[...document.querySelectorAll('#merge-form input[name="cards"]:checked')].map(e=>e.value),sum=state.cards.filter(c=>ids.includes(c.id)).reduce((s,c)=>s+c.face_cents,0);$('#merge-total').textContent=`已选 ${ids.length} 张 · 合计 ¥${yuan(sum)}`;}}catch(err){imported=[];toast(err.message);}});
document.addEventListener('input',e=>{dirty=true;if(e.target.id==='f-code'&&$('#join-confirm')){clearTimeout(invitePreviewTimer);invitePreviewSequence++;$('#join-confirm').disabled=true;$('#join-confirm').textContent='核对邀请码后就能加入';$('#pair-preview').textContent='';$('#accept-form .error-text').textContent='';try{readInviteCode(e.target.value);invitePreviewTimer=setTimeout(previewInvite,350);}catch{}}if(e.target.closest('#odds-form'))updateOddsForm();if(e.target.closest('#prize-form'))updatePrice();if(e.target.closest('#import-form')&&e.target.id!=='import-file'){imported=[];$('#import-preview').innerHTML='<p class="subtext mt">内容已变更，请重新解析预览。</p>';}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('hashchange',()=>{if(state)incoming();else{const code=new URLSearchParams(location.hash.slice(1)).get('join');if(code)joinDialog(code);}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state&&!busy&&!dialog.open&&!dirty)refresh().catch(()=>{});});
setInterval(()=>{if(state&&!busy&&!dialog.open&&!dirty&&document.visibilityState==='visible')refresh().catch(()=>{});},60000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
boot();
